@Bean
MessageChannel ordersTap() { return MessageChannels.queue(1000).get(); }  // bounded tap buffer

@Bean
IntegrationFlow orders(OrderService orderService) {
    return IntegrationFlow.from("orders")
        .wireTap("ordersTap", wt -> wt.timeout(200))    // copy to secondary channel, capped wait
        .handle(orderService, "process")                // primary flow unchanged
        .get();
}

public void onMessage(Message m) {
    try (JMSContext tapCtx = cf.createContext()) {          // separate context; never the consume session
        JMSProducer tap = tapCtx.createProducer()
            .completionListener(new CountingListener(delivered, dropped)); // async, callback off-thread
        tap.send(tapQueue, copyOf(tapCtx, m));              // independent copy: body + needed properties
    } catch (JMSException e) {
        dropped.increment();                                // explicit, visible loss policy
    }
    primaryProducer.send(m);                                // original, unchanged
}
